:root {
  --ink: #030607;
  --panel: rgba(7, 12, 14, 0.92);
  --panel2: rgba(10, 18, 18, 0.8);
  --bone: #e8e4d6;
  --muted: #7f9188;
  --acid: #a6ff32;
  --acid-dim: #5f9e1d;
  --amber: #ffb32b;
  --red: #ff364f;
  --cyan: #58e2ff;
  --violet: #ad7bff;
  --line: rgba(166, 255, 50, 0.2);
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: #020405;
  overscroll-behavior: none;
  touch-action: none;
}
body {
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: "Trebuchet MS", "Arial Narrow", Arial, sans-serif;
  color: var(--bone);
  background:
    radial-gradient(ellipse at 50% 20%, rgba(48, 79, 44, 0.18), transparent 42%),
    radial-gradient(ellipse at 80% 85%, rgba(91, 19, 28, 0.2), transparent 38%),
    #020405;
}
body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  opacity: 0.28;
  background-image:
    linear-gradient(rgba(110, 150, 105, 0.08) 1px, transparent 1px),
    linear-gradient(90deg, rgba(110, 150, 105, 0.08) 1px, transparent 1px);
  background-size: 72px 72px;
  mask-image: radial-gradient(circle at 50% 45%, #000, transparent 72%);
}
button, input { font: inherit; }
button { cursor: pointer; }
button:focus-visible, input:focus-visible { outline: 2px solid var(--acid); outline-offset: 2px; }
.hidden { display: none !important; }

#app {
  position: relative;
  width: 100vw;
  height: 100dvh;
  max-width: calc(100dvh * 0.5625);
  max-height: 100dvh;
  overflow: hidden;
  isolation: isolate;
  font-size: 10px;
  background: #030607;
  box-shadow: 0 0 0 1px rgba(155, 255, 62, 0.08), 0 0 70px rgba(0, 0, 0, 0.95), 0 0 90px rgba(141, 255, 54, 0.045);
}
@media (min-width: 760px) and (min-height: 700px) {
  #app { border-left: 1px solid rgba(166,255,50,.12); border-right: 1px solid rgba(166,255,50,.12); }
}

.screen {
  position: absolute;
  inset: 0;
  display: none;
}
.screen.active { display: block; }
.stage-holder {
  position: absolute;
  inset: 0;
  overflow: hidden;
  background: #030607;
}
#gl {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  outline: none;
  touch-action: none;
}

/* ───────────────────────────── MENU ───────────────────────────── */
.menu-screen { background: #030607; }
.menu-screen::after,
.game-stage::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(0,0,0,.42) 0%, transparent 18%, transparent 72%, rgba(0,0,0,.66) 100%),
    radial-gradient(ellipse at center, transparent 38%, rgba(0,0,0,.58) 100%);
  mix-blend-mode: multiply;
}
.scanlines {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  opacity: 0.14;
  background: repeating-linear-gradient(0deg, transparent 0 3px, rgba(0,0,0,.35) 3px 4px);
  mix-blend-mode: multiply;
}
.menu-ui {
  position: absolute;
  inset: 0;
  z-index: 5;
  display: flex;
  flex-direction: column;
  padding: calc(var(--safe-top) + 1.4rem) 1.8rem calc(var(--safe-bottom) + 1.5rem);
  pointer-events: none;
}
.menu-ui > * { pointer-events: auto; }
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 3.6rem;
}
.brand {
  display: flex;
  align-items: center;
  gap: 0.8rem;
  font-size: 0.95rem;
  font-weight: 800;
  letter-spacing: 0.24em;
  color: rgba(232, 228, 214, 0.72);
  text-transform: uppercase;
  text-shadow: 0 1px 0 #000;
}
.brand::before {
  content: "";
  width: 1.5rem;
  height: 1.5rem;
  border: 1px solid var(--acid);
  box-shadow: inset 0 0 0.8rem rgba(166,255,50,.34), 0 0 1rem rgba(166,255,50,.2);
  background:
    linear-gradient(45deg, transparent 46%, var(--acid) 47% 52%, transparent 53%),
    linear-gradient(-45deg, transparent 46%, var(--acid) 47% 52%, transparent 53%);
  transform: rotate(45deg) scale(.7);
}
.brand small { color: var(--acid); font-size: .8rem; letter-spacing: .18em; }
.topbar-actions { display: flex; gap: 0.8rem; }
.icon-btn {
  width: 3.4rem;
  height: 3.4rem;
  display: grid;
  place-items: center;
  color: var(--bone);
  border: 1px solid rgba(200, 226, 205, 0.2);
  background: rgba(3, 9, 10, 0.64);
  border-radius: 0.5rem;
  font-size: 1.5rem;
  font-weight: 900;
  box-shadow: inset 0 0 1.6rem rgba(166, 255, 50, 0.04);
  backdrop-filter: blur(6px);
}
.icon-btn:active { transform: translateY(1px); border-color: var(--acid); color: var(--acid); }
.icon-btn svg { width: 1.55rem; height: 1.55rem; }
.icon-btn .muted-mark { display: none; }
.icon-btn.is-muted .sound-wave { display: none; }
.icon-btn.is-muted .muted-mark { display: block; }

.hero {
  position: relative;
  margin-top: clamp(2rem, 7vh, 6rem);
  text-align: left;
  text-shadow: 0 0.3rem 1rem rgba(0,0,0,.9);
}
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: .7rem;
  padding: 0.48rem 0.8rem 0.44rem;
  font-size: 0.82rem;
  font-weight: 800;
  letter-spacing: 0.2em;
  color: var(--acid);
  border: 1px solid rgba(166,255,50,.3);
  background: rgba(6, 16, 9, 0.66);
  clip-path: polygon(0 0, 100% 0, 100% 72%, 94% 100%, 0 100%);
}
.eyebrow::before { content:""; width:.5rem; height:.5rem; border-radius:50%; background:var(--red); box-shadow:0 0 1rem var(--red); animation:pulse 1.2s infinite; }
.logo {
  margin: 0.5rem 0 0;
  font-family: Impact, "Arial Black", "Arial Narrow", sans-serif;
  font-weight: 900;
  line-height: .77;
  letter-spacing: 0.01em;
  transform: skewY(-2deg);
}
.logo .main {
  display: block;
  font-size: clamp(7.4rem, 22cqw, 12rem);
  color: #e9e4d1;
  background: linear-gradient(180deg, #fffbe8 0%, #d9d1b6 22%, #6f6c5c 48%, #f7efcc 50%, #8b8a75 69%, #dbd7c5 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 .5rem 0 rgba(0,0,0,.6)) drop-shadow(0 0 2.1rem rgba(166,255,50,.14));
  -webkit-text-stroke: 1px rgba(255, 250, 219, .28);
}
.logo .sub {
  display: block;
  margin-top: .6rem;
  padding-left: .2rem;
  font-size: clamp(1.65rem, 5.2cqw, 3rem);
  letter-spacing: .19em;
  color: var(--acid);
  -webkit-text-fill-color: var(--acid);
  text-shadow: 0 0 .7rem rgba(166,255,50,.5), 0 .25rem 0 #000;
  transform: skewY(2deg);
}
.logo .sub em {
  font-style: normal;
  color: var(--red);
  text-shadow: 0 0 .8rem rgba(255,54,79,.45), 0 .25rem 0 #000;
}
.tagline {
  margin-top: 1.5rem;
  max-width: 25rem;
  font-size: 1.02rem;
  font-weight: 700;
  letter-spacing: .08em;
  line-height: 1.45;
  color: rgba(229, 233, 215, 0.72);
  text-transform: uppercase;
}
.tagline strong { color: var(--amber); }

.menu-panel {
  margin-top: auto;
  position: relative;
  padding: 1.35rem 1.2rem 1.1rem;
  background:
    linear-gradient(180deg, rgba(15, 24, 22, 0.88), rgba(4, 8, 9, 0.94)),
    repeating-linear-gradient(-45deg, rgba(255,255,255,.02) 0 2px, transparent 2px 8px);
  border: 1px solid rgba(173, 221, 177, 0.16);
  border-top-color: rgba(166,255,50,.38);
  clip-path: polygon(0 0, calc(100% - 1.6rem) 0, 100% 1.6rem, 100% 100%, 0 100%);
  box-shadow: 0 -1.6rem 4rem rgba(0,0,0,.4), inset 0 0 4rem rgba(166,255,50,.025);
  backdrop-filter: blur(8px);
}
.menu-panel::before {
  content: "";
  position: absolute;
  left: 0; top: 0;
  width: 100%; height: .25rem;
  background: repeating-linear-gradient(90deg, var(--acid) 0 1.2rem, #0a0f0b 1.2rem 2.4rem);
  opacity: .55;
}
.panel-label {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: .72rem;
  font-size: .78rem;
  font-weight: 800;
  letter-spacing: .24em;
  color: var(--muted);
  text-transform: uppercase;
}
.panel-label b { color: var(--acid); font-weight: 800; letter-spacing: .1em; }
.segmented {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: .5rem;
  margin-bottom: .85rem;
}
.diff-btn {
  position: relative;
  min-height: 4.4rem;
  padding: .55rem .3rem .45rem;
  color: rgba(232, 228, 214, 0.64);
  border: 1px solid rgba(181, 208, 185, 0.14);
  background: rgba(0,2,3,.58);
  font-size: .78rem;
  font-weight: 800;
  letter-spacing: .12em;
  text-transform: uppercase;
  transition: .16s ease;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - .7rem), calc(100% - .7rem) 100%, 0 100%);
}
.diff-btn strong { display: block; font-size: 1.14rem; letter-spacing: .08em; color: rgba(232,228,214,.85); margin-bottom: .2rem; }
.diff-btn span { display: block; font-size: .63rem; color: var(--muted); letter-spacing: .06em; }
.diff-btn.selected {
  color: var(--bone);
  border-color: rgba(166,255,50,.72);
  background: linear-gradient(180deg, rgba(70, 111, 34, .22), rgba(7,18,9,.7));
  box-shadow: inset 0 0 1.5rem rgba(166,255,50,.11), 0 0 1.1rem rgba(166,255,50,.09);
}
.diff-btn.selected strong { color: var(--acid); }
.diff-btn.selected::after {
  content: "";
  position: absolute;
  right: .55rem; top: .5rem;
  width: .42rem; height: .42rem;
  border-radius: 50%;
  background: var(--acid);
  box-shadow: 0 0 1rem var(--acid);
}
.diff-btn[data-diff="nightmare"].selected { border-color: rgba(255,54,79,.72); background: linear-gradient(180deg, rgba(119, 20, 35, .24), rgba(22,5,8,.8)); box-shadow: inset 0 0 1.5rem rgba(255,54,79,.12), 0 0 1.1rem rgba(255,54,79,.1); }
.diff-btn[data-diff="nightmare"].selected strong { color: #ff7788; }
.diff-btn[data-diff="nightmare"].selected::after { background: var(--red); box-shadow: 0 0 1rem var(--red); }

.cta {
  position: relative;
  width: 100%;
  min-height: 6.2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0 1.35rem;
  border: 1px solid rgba(202,255,121,.58);
  color: #0c1308;
  background: linear-gradient(105deg, #d6ff78 0%, #9dff38 45%, #66b51f 100%);
  box-shadow: 0 0 2.1rem rgba(166,255,50,.18), inset 0 1px 0 rgba(255,255,255,.5), inset 0 -.35rem 0 rgba(16,48,3,.38);
  clip-path: polygon(0 0, calc(100% - 1.5rem) 0, 100% 1.5rem, 100% 100%, 1.5rem 100%, 0 calc(100% - 1.5rem));
  font-size: 1.55rem;
  font-weight: 900;
  letter-spacing: .1em;
  text-transform: uppercase;
  transition: .12s ease;
}
.cta:hover { filter: brightness(1.08); }
.cta:active { transform: translateY(2px); filter: brightness(.95); }
.cta .arrow { font-size: 2.5rem; line-height: 1; opacity: .72; }
.cta small { display: block; font-size: .67rem; letter-spacing: .16em; opacity: .65; margin-top: .15rem; }
.menu-row { display: grid; grid-template-columns: 1fr 1fr; gap: .65rem; margin-top: .7rem; }
.ghost {
  min-height: 4.2rem;
  padding: .5rem .8rem;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .6rem;
  border: 1px solid rgba(180, 207, 184, 0.17);
  color: rgba(232,228,214,.82);
  background: rgba(3, 8, 9, 0.58);
  font-size: .82rem;
  font-weight: 800;
  letter-spacing: .1em;
  text-transform: uppercase;
}
.ghost:active { border-color: var(--acid); color: var(--acid); }
.ghost .glyph { color: var(--amber); font-size: 1.15rem; }
.best-line {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: .8rem;
  padding-top: .72rem;
  border-top: 1px dashed rgba(178, 202, 181, 0.13);
  font-size: .7rem;
  letter-spacing: .12em;
  color: var(--muted);
}
.best-line strong { color: var(--amber); font-size: .95rem; letter-spacing: .09em; text-shadow: 0 0 .8rem rgba(255,179,43,.25); }
.credits {
  margin-top: .36rem;
  text-align: center;
  font-size: .58rem;
  letter-spacing: .11em;
  color: rgba(145, 162, 150, .55);
  line-height: 1.5;
}
.credits b { color: rgba(210, 228, 197, .8); }
.menu-fade { animation: menu-in .9s cubic-bezier(.18,.8,.28,1) both; }
.hero.menu-fade { animation-delay: .12s; }
.menu-panel.menu-fade { animation-delay: .25s; }
@keyframes menu-in { from { opacity: 0; transform: translateY(1.5rem); } to { opacity: 1; transform: translateY(0); } }
@keyframes pulse { 0%,100% { opacity: 1; } 50% { opacity: .35; } }

/* ───────────────────────────── GAME ───────────────────────────── */
.game-screen {
  display: none;
  grid-template-rows: auto minmax(0, 1fr) auto;
  background: #030607;
}
.game-screen.active { display: grid; }
.game-hud {
  position: relative;
  z-index: 3;
  padding: calc(var(--safe-top) + .55rem) 1.1rem .55rem;
  background:
    linear-gradient(180deg, rgba(4,8,9,.98) 0%, rgba(5,9,10,.96) 76%, rgba(5,9,10,.84) 100%),
    repeating-linear-gradient(-45deg, rgba(255,255,255,.025) 0 1px, transparent 1px 8px);
  border-bottom: 1px solid rgba(143, 222, 91, .24);
  box-shadow: 0 1.2rem 2.4rem rgba(0,0,0,.38);
}
.game-hud::after {
  content:"";
  position:absolute; left:0; bottom:-1px; width:100%; height:2px;
  background: linear-gradient(90deg, transparent, var(--acid), transparent);
  opacity:.45;
}
.hud-top { display: grid; grid-template-columns: 1.1fr 1.2fr .95fr; gap: .7rem; align-items: center; }
.hud-label { font-size: .62rem; letter-spacing: .18em; color: var(--muted); font-weight: 800; text-transform: uppercase; }
.score-box .hud-label { color: rgba(166,255,50,.68); }
.score-val {
  margin-top: .08rem;
  font-family: "Arial Narrow", "Trebuchet MS", sans-serif;
