    }
    const bk = t - st.barkAt;
    if (bk > 0 && bk < .55) {
      const open = Math.sin(Math.min(1, bk / .2) * Math.PI) * .28;
      jaw.rotation.z = -open;
      jaw.position.y = -.18 - open * .07;
      tongue.visible = true;
      tongue.position.y = -.12 - open * .08;
      head.rotation.z += Math.sin(bk * 42) * .035;
