    antennaTip.scale.setScalar(1 + Math.sin(t * 5.2) * .18);
    tailGlow.material.opacity = .22 + Math.sin(t * 5) * .12;
    root.position.y = opts2.baseY != null ? opts2.baseY + breathe : root.position.y;
  };
