(async () => {
  require('node:fs').mkdirSync(OUT, { recursive: true });
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
  page.setDefaultTimeout(30000);
  const errors = [];
  const logs = [];
  page.on('pageerror', e => { errors.push('PAGEERROR: ' + e.message); console.log('PAGEERROR', e.message); });
  page.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') { logs.push(m.type() + ': ' + m.text()); } });
  const resp = await page.goto(URL, { waitUntil: 'load', timeout: 45000 });
  console.log('HTTP', resp && resp.status());
  await page.waitForTimeout(1800);

  // menu screenshot
  await page.screenshot({ path: join(OUT, '01-menu-mobile.png') });
  console.log('menu shot');

  // check element overlap: stage vs hud/controls
  const layout = await page.evaluate(() => {
    const r = id => { const el = document.getElementById(id); if (!el) return null; const b = el.getBoundingClientRect(); return { id, x: +b.x.toFixed(1), y: +b.y.toFixed(1), w: +b.width.toFixed(1), h: +b.height.toFixed(1) }; };
    return {
      canvas: r('gl'), menuStage: r('menuStage'), gameStage: r('gameStage'),
      hud: document.querySelector('.game-hud') ? (() => { const b = document.querySelector('.game-hud').getBoundingClientRect(); return { x: +b.x.toFixed(1), y: +b.y.toFixed(1), w: +b.width.toFixed(1), h: +b.height.toFixed(1) }; })() : null,
      controls: document.querySelector('.controls') ? (() => { const b = document.querySelector('.controls').getBoundingClientRect(); return { x: +b.x.toFixed(1), y: +b.y.toFixed(1), w: +b.width.toFixed(1), h: +b.height.toFixed(1) }; })() : null,
      eventLine: r('eventLine'),
      menuPanel: document.querySelector('.menu-panel') ? (() => { const b = document.querySelector('.menu-panel').getBoundingClientRect(); return { x: +b.x.toFixed(1), y: +b.y.toFixed(1), w: +b.width.toFixed(1), h: +b.height.toFixed(1) }; })() : null,
    };
  });
  console.log('LAYOUT', JSON.stringify(layout));

  // start run
  await page.tap('#startBtn');
  await page.waitForTimeout(1200);
  await page.screenshot({ path: join(OUT, '02-game-start-mobile.png') });
  console.log('game start shot');

  const state1 = await page.evaluate(() => window.WUMMI && window.WUMMI.state());
  console.log('STATE1', JSON.stringify(state1));

  // launch
  for (let i = 0; i < 3; i++) { await page.tap('#launchBtn'); await page.waitForTimeout(500); }
  await page.waitForTimeout(2500);
  await page.screenshot({ path: join(OUT, '03-game-launched-mobile.png') });
  const state2 = await page.evaluate(() => window.WUMMI && window.WUMMI.state());
  console.log('STATE2', JSON.stringify(state2));

  // flip
  await page.tap('#leftBtn'); await page.waitForTimeout(300); await page.tap('#rightBtn');
  await page.waitForTimeout(1200);
  await page.screenshot({ path: join(OUT, '04-game-flip-mobile.png') });
  const state3 = await page.evaluate(() => window.WUMMI && window.WUMMI.state());
  console.log('STATE3', JSON.stringify(state3));

  // force k9
  await page.evaluate(() => window.WUMMI.forceK9 && window.WUMMI.forceK9());
  await page.waitForTimeout(1400);
  await page.screenshot({ path: join(OUT, '05-game-k9-mobile.png') });
  const state4 = await page.evaluate(() => window.WUMMI && window.WUMMI.state());
  console.log('STATE4', JSON.stringify(state4));

  // score pumping to trigger stage progression
  const prog = await page.evaluate(async () => {
    if (!window.WUMMI) return null;
    const before = window.WUMMI.stage();
    window.WUMMI.score(15000);
    return { before, after: window.WUMMI.stage() };
  });
  console.log('PROG', JSON.stringify(prog));
  await page.waitForTimeout(1500);
  await page.screenshot({ path: join(OUT, '06-game-stage2-mobile.png') });

  // ranking modal
  await page.evaluate(() => window.WUMMI.pause());
  await page.waitForTimeout(500);
  await page.screenshot({ path: join(OUT, '07-pause-mobile.png') });
  const pauseText = await page.evaluate(() => document.getElementById('modalLayer').textContent);
  console.log('PAUSE MODAL', pauseText && pauseText.slice(0, 200));

  // desktop
