  if (!run) return;
  run.k9 = clamp(run.k9 + amount, 0, 100);
  if (run.k9 >= 100 && run.k9Fx <= 0 && run.k9Ready <= 0) {
    run.k9Ready = .55;
    showEvent('K9-WUT BEREIT');
  }
}

