const { createRequire } = require('node:module');
const { join } = require('node:path');
const { readFileSync } = require('node:fs');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const req = createRequire(join(runtime, 'package.json'));
const { chromium } = req('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
  page.on('pageerror', e => console.log('PAGEERROR', e.message, e.stack));
  page.on('console', m => console.log('CONSOLE', m.type(), m.text()));
  await page.goto('http://127.0.0.1:3000/', { waitUntil: 'load' });
  await page.waitForTimeout(800);
  await page.click('#startBtn');
  await page.waitForTimeout(1200);
  const info = await page.evaluate(() => ({
    state: window.WUMMI.state(),
    launchDisabled: document.getElementById('launchBtn').disabled,
    launchHTML: document.getElementById('launchBtn').innerHTML,
    sector: document.getElementById('sectorVal').textContent,
    objective: document.getElementById('objective').textContent,
    score: document.getElementById('scoreVal').textContent,
    balls: document.getElementById('ballPips').children.length,
  }));
  console.log(JSON.stringify(info, null, 2));
  // call launch directly
  const launched = await page.evaluate(() => { try { window.WUMMI.launch(); return 'ok'; } catch (e) { return e.message; } });
  console.log('DIRECT LAUNCH', launched);
  await page.waitForTimeout(500);
  console.log(await page.evaluate(() => ({ disabled: document.getElementById('launchBtn').disabled, html: document.getElementById('launchBtn').innerHTML })));
  await browser.close();
})();

