const { createRequire } = require('node:module');
const { join } = require('node:path');
const { readFileSync } = require('node:fs');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const req = createRequire(join(runtime, 'package.json'));
const { chromium } = req('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
  page.on('pageerror', e => console.log('PAGEERROR', e.message));
  await page.goto('http://127.0.0.1:3000/', { waitUntil: 'load' });
  await page.waitForTimeout(1800);
  const log = async label => {
    const info = await page.evaluate(() => ({
      state: window.WUMMI.state(),
      hidden: document.hidden,
      dis: document.getElementById('launchBtn').disabled,
      txt: document.getElementById('launchBtn').textContent,
      st: document.getElementById('objective').textContent,
      modal: document.getElementById('modalLayer').className,
    }));
    console.log(label, JSON.stringify(info));
  };
  await log('before menu shot');
  await page.screenshot({ path: '/tmp/opencode/shots/diag4-menu.png' });
  await log('after menu shot');
  const layout = await page.evaluate(() => {
    const r = id => { const el = document.getElementById(id); if (!el) return null; const b = el.getBoundingClientRect(); return { id, x: +b.x.toFixed(1), y: +b.y.toFixed(1), w: +b.width.toFixed(1), h: +b.height.toFixed(1) }; };
    return { canvas: r('gl'), menuStage: r('menuStage'), gameStage: r('gameStage') };
  });
  console.log('layout', JSON.stringify(layout));
  await page.tap('#startBtn');
  await page.waitForTimeout(1200);
  await log('after start');
  await page.screenshot({ path: '/tmp/opencode/shots/diag4-game.png' });
  await log('after game shot');
  await browser.close();
})();

