const { createRequire } = require('node:module');
const { join } = require('node:path');
const { readFileSync } = require('node:fs');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const req = createRequire(join(runtime, 'package.json'));
const { chromium } = req('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
  await page.goto('http://127.0.0.1:3000/', { waitUntil: 'load' });
  await page.waitForTimeout(1500);
  const info = await page.evaluate(() => {
    const r = sel => { const el = document.querySelector(sel); if (!el) return null; const b = el.getBoundingClientRect(); const cs = getComputedStyle(el); return { sel, x:+b.x.toFixed(1), y:+b.y.toFixed(1), w:+b.width.toFixed(1), h:+b.height.toFixed(1), fs: cs.fontSize, pad: cs.padding, ov: cs.overflow, cw: el.clientWidth, sw: el.scrollWidth }; };
    return {
      app: r('#app'), ui: r('.menu-ui'), topbar: r('.topbar'), hero: r('.hero'), logoMain: r('.logo .main'),
      panel: r('.menu-panel'), seg: r('.segmented'), cta: r('#startBtn'), row: r('.menu-row'), credits: r('.credits'),
      viewport: { w: innerWidth, h: innerHeight, dpr: devicePixelRatio },
      fontSize: getComputedStyle(document.getElementById('app')).fontSize,
      htmlFont: getComputedStyle(document.documentElement).fontSize,
    };
  });
  console.log(JSON.stringify(info, null, 2));
  await browser.close();
})();

