const { createRequire } = require('node:module');
const { join } = require('node:path');
const { readFileSync, mkdirSync } = require('node:fs');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const req = createRequire(join(runtime, 'package.json'));
const { chromium } = req('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const URL = process.env.URL || 'http://127.0.0.1:3000/';
const OUT = '/tmp/opencode/shots';
const sleep = ms => new Promise(r => setTimeout(r, ms));

(async () => {
  mkdirSync(OUT, { recursive: true });
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
  page.setDefaultTimeout(15000);
  const errors = [];
  const consoleErrors = [];
  page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message); });
  page.on('console', m => { if (m.type() === 'error') consoleErrors.push(m.text()); });
  await page.goto(URL, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(1200);
  await page.screenshot({ path: join(OUT, 'm01-menu.png') });

  const state = async () => page.evaluate(() => ({
    state: window.WUMMI.state(), score: window.WUMMI.score(), stage: window.WUMMI.stage(),
    launchDisabled: document.getElementById('launchBtn').disabled,
    launchText: document.getElementById('launchBtn').textContent,
    modal: document.getElementById('modalLayer').className,
    event: document.getElementById('eventLine').textContent,
  }));

  await page.tap('#startBtn');
  await page.waitForTimeout(900);
  console.log('START', JSON.stringify(await state()));
  await page.screenshot({ path: join(OUT, 'm02-game-hold.png') });

  await page.tap('#launchBtn');
  await page.waitForTimeout(3500);
  console.log('LAUNCH', JSON.stringify(await state()));
  await page.screenshot({ path: join(OUT, 'm03-game-live.png') });

  // Flip repeatedly to keep the ball alive and score.
  for (let i = 0; i < 8; i++) {
    await page.tap(i % 2 ? '#leftBtn' : '#rightBtn');
    await sleep(260);
  }
  await page.screenshot({ path: join(OUT, 'm04-game-flip.png') });
  console.log('FLIP', JSON.stringify(await state()));

  // K9 special.
  await page.evaluate(() => window.WUMMI.forceK9());
  await page.waitForTimeout(900);
  await page.screenshot({ path: join(OUT, 'm05-k9.png') });
  console.log('K9', JSON.stringify(await state()));
  await page.waitForTimeout(1600);

  // Clear sector with a second K9 strike.
  await page.evaluate(() => window.WUMMI.forceK9());
  await page.waitForTimeout(2600);
  await page.screenshot({ path: join(OUT, 'm06-sector-transition.png') });
  console.log('SECTOR', JSON.stringify(await state()));
  await page.waitForTimeout(2800);
  console.log('SECTOR2', JSON.stringify(await state()));
  await page.screenshot({ path: join(OUT, 'm07-sector2.png') });

  // Ranking modal.
  await page.tap('#pauseBtn');
  await page.waitForTimeout(500);
  await page.screenshot({ path: join(OUT, 'm08-pause.png') });
  console.log('PAUSE', JSON.stringify(await state()));
  const rankingVisible = await page.locator('#pauseRankBtn').count().catch(() => 0);
  console.log('pause ranking btn count', rankingVisible);
  const pauseHtml = await page.evaluate(() => document.getElementById('modalCard').innerText);
  console.log('PAUSE TEXT', JSON.stringify(pauseHtml.slice(0, 240)));
  // find ranking button in pause modal
  const rankBtn = page.locator('#modalCard button').filter({ hasText: /RANGLISTE|RANG/i }).first();
  if (await rankBtn.count()) { await rankBtn.click(); await page.waitForTimeout(450); await page.screenshot({ path: join(OUT, 'm09-ranking.png') }); console.log('RANKING', JSON.stringify(await state())); }
  const closeBtn = page.locator('#rankingClose');
  if (await closeBtn.count()) { await closeBtn.click(); await page.waitForTimeout(250); }

  // Resume and force game over with a nonzero score.
  await page.evaluate(() => { window.WUMMI.addScore(123450); });
  await page.evaluate(() => window.WUMMI.end());
  await page.waitForTimeout(1300);
  await page.screenshot({ path: join(OUT, 'm10-gameover.png') });
  console.log('GAMEOVER', JSON.stringify(await state()));
  console.log('GAMEOVER TEXT', JSON.stringify((await page.evaluate(() => document.getElementById('modalCard').innerText)).slice(0, 400)));

  // Desktop.
  const desk = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const deskErrors = [];
  desk.on('pageerror', e => { deskErrors.push(e.message); console.log('DESK PAGEERROR', e.message); });
  await desk.goto(URL, { waitUntil: 'load' });
  await desk.waitForTimeout(1200);
  await desk.screenshot({ path: join(OUT, 'd01-menu.png') });
  await desk.evaluate(() => window.WUMMI.start());
  await desk.waitForTimeout(900);
  await desk.evaluate(() => window.WUMMI.launch());
  await desk.waitForTimeout(1300);
  await desk.screenshot({ path: join(OUT, 'd02-game.png') });
  const deskRects = await desk.evaluate(() => {
    const rect = sel => { const b = document.querySelector(sel)?.getBoundingClientRect(); return b ? { x:+b.x.toFixed(1), y:+b.y.toFixed(1), w:+b.width.toFixed(1), h:+b.height.toFixed(1) } : null; };
    return { app: rect('#app'), hud: rect('.game-hud'), stage: rect('.game-stage'), controls: rect('.controls') };
  });
  console.log('DESK RECTS', JSON.stringify(deskRects));
  console.log('DESK STATE', JSON.stringify(await desk.evaluate(() => ({ state: window.WUMMI.state(), score: window.WUMMI.score(), stage: window.WUMMI.stage() }))));

  // Tablet.
  const tab = await browser.newPage({ viewport: { width: 834, height: 1194 } });
  tab.on('pageerror', e => { deskErrors.push('tablet: ' + e.message); console.log('TAB PAGEERROR', e.message); });
  await tab.goto(URL, { waitUntil: 'load' });
  await tab.waitForTimeout(1000);
  await tab.screenshot({ path: join(OUT, 't01-menu.png') });

  console.log('ERRORS', JSON.stringify(errors));
  console.log('CONSOLE_ERRORS', JSON.stringify(consoleErrors));
  console.log('DESK_ERRORS', JSON.stringify(deskErrors));
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

