const { createRequire } = require('node:module');
const { join } = require('node:path');
const { readFileSync, mkdirSync } = require('node:fs');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const req = createRequire(join(runtime, 'package.json'));
const { chromium } = req('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const URL = process.env.URL || 'http://127.0.0.1:3000/';
const OUT = '/tmp/opencode/shots';
const sleep = ms => new Promise(r => setTimeout(r, ms));

(async () => {
  mkdirSync(OUT, { recursive: true });
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
  page.setDefaultTimeout(20000);
  const errors = [];
  const consoleErrors = [];
  page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message); });
  page.on('console', m => { if (m.type() === 'error') consoleErrors.push(m.text()); });
  await page.goto(URL, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(1200);
  await page.screenshot({ path: join(OUT, 'm01-menu.png') });
  const snap = () => page.evaluate(() => ({ ...window.WUMMI.snapshot(), ui: window.WUMMI.state(), launchDisabled: document.getElementById('launchBtn').disabled, modal: document.getElementById('modalLayer').className }));

  await page.tap('#startBtn');
  await page.waitForTimeout(900);
  await page.screenshot({ path: join(OUT, 'm02-game-hold.png') });
  console.log('START', JSON.stringify(await snap()));

  await page.tap('#launchBtn');
  await sleep(4500);
  await page.screenshot({ path: join(OUT, 'm03-game-live.png') });
  console.log('LIVE', JSON.stringify(await snap()));

  // Keep playing / flip a bit.
  for (let i = 0; i < 10; i++) { await page.tap(i % 2 ? '#leftBtn' : '#rightBtn'); await sleep(200); }
  await page.screenshot({ path: join(OUT, 'm04-game-flip.png') });
  console.log('FLIP', JSON.stringify(await snap()));

  // First K9 strike and wait for the full animation using simulation state.
  await page.evaluate(() => window.WUMMI.forceK9());
  await page.waitForTimeout(1200);
  await page.screenshot({ path: join(OUT, 'm05-k9.png') });
  await page.waitForFunction(() => window.WUMMI.snapshot().k9Fx <= 0, null, { timeout: 20000 });
  await page.screenshot({ path: join(OUT, 'm05b-k9-end.png') });
  console.log('K9-1', JSON.stringify(await snap()));

  // Second K9 strike should finish the sector.
  await page.evaluate(() => window.WUMMI.forceK9());
  await page.waitForFunction(() => window.WUMMI.snapshot().stageClearTimer > 0 || window.WUMMI.snapshot().stage > 1, null, { timeout: 20000 });
  await page.screenshot({ path: join(OUT, 'm06-sector-clear.png') });
  console.log('CLEAR', JSON.stringify(await snap()));
  await page.waitForFunction(() => window.WUMMI.snapshot().stage > 1, null, { timeout: 20000 });
  await page.waitForTimeout(1200);
  await page.screenshot({ path: join(OUT, 'm07-sector2.png') });
  console.log('SECTOR2', JSON.stringify(await snap()));

  // Pause + ranking.
  await page.tap('#pauseBtn');
  await page.waitForTimeout(600);
  await page.screenshot({ path: join(OUT, 'm08-pause.png') });
  console.log('PAUSE', JSON.stringify(await snap()));
  const pauseText = await page.evaluate(() => document.getElementById('modalCard').innerText);
  console.log('PAUSE TEXT', JSON.stringify(pauseText.slice(0, 300)));

  // Close pause -> menu -> ranking.
  const pauseBtn2 = page.locator('#pauseMenuBtn');
  if (await pauseBtn2.count()) { await pauseBtn2.click(); await page.waitForTimeout(500); }
  await page.waitForTimeout(300);
  await page.tap('#rankingBtn');
  await page.waitForTimeout(600);
  await page.screenshot({ path: join(OUT, 'm09-ranking.png') });
  console.log('RANKING TEXT', JSON.stringify((await page.evaluate(() => document.getElementById('modalCard').innerText)).slice(0, 500)));
  const rankClose = page.locator('#rankingClose');
  if (await rankClose.count()) { await rankClose.click(); await page.waitForTimeout(300); }

  // Briefing.
  await page.tap('#briefingBtn');
  await page.waitForTimeout(500);
  await page.screenshot({ path: join(OUT, 'm10-briefing.png') });
  const briefClose = page.locator('#briefClose');
  if (await briefClose.count()) { await briefClose.click(); await page.waitForTimeout(300); }

  // Start again, score, game over.
  await page.tap('#startBtn');
  await page.waitForTimeout(700);
  await page.evaluate(() => window.WUMMI.addScore(123450));
  await page.evaluate(() => window.WUMMI.end());
  await page.waitForTimeout(1400);
  await page.screenshot({ path: join(OUT, 'm11-gameover.png') });
  console.log('GAMEOVER', JSON.stringify(await snap()));
  console.log('GAMEOVER TEXT', JSON.stringify((await page.evaluate(() => document.getElementById('modalCard').innerText)).slice(0, 500)));
  await page.screenshot({ path: join(OUT, 'm12-gameover-full.png'), fullPage: false });

  // Desktop.
  const desk = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const deskErrors = [];
  desk.on('pageerror', e => { deskErrors.push(e.message); console.log('DESK PAGEERROR', e.message); });
  await desk.goto(URL, { waitUntil: 'load' });
  await desk.waitForTimeout(1200);
  await desk.screenshot({ path: join(OUT, 'd01-menu.png') });
  await desk.evaluate(() => window.WUMMI.start());
  await desk.waitForTimeout(800);
  await desk.evaluate(() => window.WUMMI.launch());
  await sleep(4500);
  await desk.screenshot({ path: join(OUT, 'd02-game.png') });
  console.log('DESK', JSON.stringify(await desk.evaluate(() => ({ ...window.WUMMI.snapshot(), ui: window.WUMMI.state() }))));

  console.log('ERRORS', JSON.stringify(errors));
  console.log('CONSOLE_ERRORS', JSON.stringify(consoleErrors));
  console.log('DESK_ERRORS', JSON.stringify(deskErrors));
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

