  console.log('CHIPS', JSON.stringify(await page.evaluate(() => document.getElementById('powerChips').innerText)));
  console.log('STATS', JSON.stringify(await page.evaluate(() => window.WUMMI.snapshot().stats)));

  // Activate a spread of powers and take a HUD shot.
  for (const p of ['flame', 'magnet', 'overdrive', 'shield', 'slow']) await page.evaluate(t => window.WUMMI.power(t), p);
  await sleep(900);
  await page.screenshot({ path: join(OUT, 'p01-powers.png') });
  console.log('CHIPS2', JSON.stringify(await page.evaluate(() => document.getElementById('powerChips').innerText)));
  console.log('SNAP', JSON.stringify(await page.evaluate(() => window.WUMMI.snapshot())));

  // Multiball.
  await page.evaluate(() => window.WUMMI.power('multiball'));
  await sleep(800);
  await page.screenshot({ path: join(OUT, 'p02-multiball.png') });
  console.log('MULTI', JSON.stringify(await page.evaluate(() => window.WUMMI.snapshot().balls)));

  // Finish a run and commit the name.
  await page.evaluate(() => { window.WUMMI.addScore(555555); window.WUMMI.end(); });
  await page.waitForTimeout(1400);
  await page.fill('#rankName', 'BANDOS7');
  await page.click('#saveName');
  await page.waitForTimeout(400);
  await page.screenshot({ path: join(OUT, 'p03-gameover-saved.png') });
  console.log('SAVE BTN', JSON.stringify(await page.evaluate(() => document.getElementById('saveName').textContent)));
  await page.click('#goRankBtn');
  await page.waitForTimeout(500);
  await page.screenshot({ path: join(OUT, 'p04-ranking.png') });
  console.log('RANK TOP', JSON.stringify(await page.evaluate(() => [...document.querySelectorAll('#modalCard tbody tr')].slice(0, 3).map(tr => tr.innerText))));
  await page.click('#rankingClose');
  await page.waitForTimeout(400);
  await page.click('#goMenuBtn');
  await page.waitForTimeout(700);
  console.log('BEST', JSON.stringify(await page.evaluate(() => document.getElementById('bestScore').textContent)));
  console.log('STORAGE', JSON.stringify(await page.evaluate(() => ({ rank: localStorage.getItem('wummi_rank_111')?.slice(0, 180), settings: localStorage.getItem('wummi_settings_111') }))));

  // Nightmare selection then start; verify 2 balls.
  await page.click('[data-diff="nightmare"]');
  await page.click('#startBtn');
  await page.waitForTimeout(700);
  console.log('NIGHTMARE', JSON.stringify(await page.evaluate(() => ({
    diff: document.getElementById('difficultyReadout').textContent,
    pips: document.querySelectorAll('.ball-pip').length,
