content.text:
:root {
  --ink: #030607;
  --panel: rgba(7, 12, 14, 0.92);
  --panel2: rgba(10, 18, 18, 0.8);
  --bone: #e8e4d6;
  --muted: #7f9188;
  --acid: #a6ff32;
  --acid-dim: #5f9e1d;
  --amber: #ffb32b;
  --red: #ff364f;
  --cyan: #58e2ff;
  --violet: #ad7bff;
  --line: rgba(166, 255, 50, 0.2);
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: #020405;
  overscroll-behavior: none;
  touch-action: none;
}
body {
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: "Trebuchet MS", "Arial Narrow", Arial, sans-serif;
  color: var(--bone);
  background:
    radial-gradient(ellipse at 50% 20%, rgba(48, 79, 44, 0.18), transparent 42%),
    radial-gradient(ellipse at 80% 85%, rgba(91, 19, 28, 0.2), transparent 38%),
    #020405;
}
body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  opacity: 0.28;
  background-image:
    linear-gradient(rgba(110, 150, 105, 0.08) 1px, transparent 1px),
    linear-gradient(90deg, rgba(110, 150, 105, 0.08) 1px, transparent 1px);
  background-size: 72px 72px;
  mask-image: radial-gradient(circle at 50% 45%, #000, transparent 72%);
}
button, input { font: inherit; }
button { cursor: pointer; }
button:focus-visible, input:focus-visible { outline: 2px solid var(--acid); outline-offset: 2px; }
.hidden { display: none !important; }

#app {
  position: relative;
  width: 100vw;
  height: 100dvh;
  max-width: calc(100dvh * 0.5625);
  max-height: 100dvh;
  overflow: hidden;
  isolation: isolate;
  container-type: inline-size;
  font-size: 10px;
  background: #030607;
  box-shadow: 0 0 0 1px rgba(155, 255, 62, 0.08), 0 0 70px rgba(0, 0, 0, 0.95), 0 0 90px rgba(141, 255, 54, 0.045);
}
@media (min-width: 760px) and (min-height: 700px) {
  #app { border-left: 1px solid rgba(166,255,50,.12); border-right: 1px solid rgba(166,255,50,.12); }
}
  border:1px solid rgba(166,255,50,.28);
  background:rgba(0,0,0,.5);
  color:var(--bone);
  font-size:1.1rem;
  font-weight:800;
  letter-spacing:.1em;
  text-transform:uppercase;
}
.name-input::placeholder { color:rgba(155,172,158,.38); }
.name-row .btn-primary { min-width:8.2rem; min-height:4.4rem; font-size:.8rem; }
.stat-grid { display:grid; grid-template-columns:1fr 1fr; gap:.55rem; margin:.9rem 0; }
.stat {
  padding:.65rem .7rem .55rem;
  border:1px solid rgba(183,208,185,.12);
  background:rgba(0,0,0,.23);
}
.stat span { display:block; font-size:.56rem; letter-spacing:.12em; color:var(--muted); text-transform:uppercase; }
.stat b { display:block; margin-top:.18rem; font-size:1.3rem; letter-spacing:.02em; color:#f1eee0; }
.stat b.acid { color:var(--acid); }
.gameover-score { font-size:4rem; font-weight:900; line-height:1; letter-spacing:-.02em; color:#ffdd93; text-shadow:0 0 1.7rem rgba(255,179,43,.2); margin:.5rem 0 .2rem; }
.new-record { display:inline-block; margin-bottom:.6rem; padding:.25rem .55rem; border:1px solid rgba(255,54,79,.35); background:rgba(255,54,79,.1); color:#ff9aa6; font-size:.62rem; font-weight:900; letter-spacing:.14em; text-transform:uppercase; }
.brief-list { display:grid; gap:.7rem; margin-top:.9rem; }
.brief-item { display:grid; grid-template-columns:2.5rem 1fr; gap:.7rem; align-items:start; padding:.65rem .7rem; border:1px solid rgba(178,204,180,.1); background:rgba(0,0,0,.2); }
.brief-item .bi-icon { width:2.5rem; height:2.5rem; display:grid; place-items:center; border:1px solid rgba(166,255,50,.2); color:var(--acid); font-size:1.1rem; font-weight:900; background:rgba(166,255,50,.035); }
.brief-item b { display:block; font-size:.72rem; letter-spacing:.08em; text-transform:uppercase; color:rgba(235,239,224,.9); }
.brief-item p { margin:.2rem 0 0; font-size:.65rem; line-height:1.45; letter-spacing:.03em; color:rgba(175,192,174,.65); }

.toast-layer { position:absolute; left:0; right:0; bottom:0; z-index:6; pointer-events:none; }
.rotate-hint { display:none; }
@media (orientation: landscape) and (max-height: 620px) {
  .rotate-hint { position:fixed; inset:0; z-index:80; display:flex; align-items:center; justify-content:center; text-align:center; padding:2rem; background:rgba(2,5,6,.94); color:var(--bone); font-size:1rem; letter-spacing:.12em; text-transform:uppercase; }
  .rotate-hint b { color:var(--acid); display:block; margin-bottom:.6rem; font-size:1.4rem; }
}
@media (max-width: 360px) {
  .menu-ui { padding-left: 1.2rem; padding-right: 1.2rem; }
  .hero { margin-top: 3rem; }
  .logo .main { font-size: 6.7rem; }
  .logo .sub { font-size: 1.45rem; letter-spacing: .14em; }
  .tagline { font-size: .86rem; }
  .menu-panel { padding-left: .9rem; padding-right: .9rem; }
  .game-hud { padding-left: .7rem; padding-right: .7rem; }
  .controls { gap: .55rem; padding-left: .7rem; padding-right: .7rem; }
  .score-val { font-size: 2.55rem; }
  .flip-btn .key { font-size: 2.1rem; }
}
@media (prefers-reduced-motion: reduce) {
  .menu-fade, .launch-btn.ready, .eyebrow::before { animation: none !important; }
}

