const { createRequire } = require('node:module');
const { join } = require('node:path');
const { readFileSync } = require('node:fs');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const req = createRequire(join(runtime, 'package.json'));
const { chromium } = req('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const sleep = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
  const errors = [], cerr = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') cerr.push(m.text()); });
  await page.goto('http://127.0.0.1:3000/', { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(900);
  await page.tap('#startBtn'); await sleep(500);
  await page.tap('#launchBtn'); await sleep(2200);
  await page.screenshot({ path: '/tmp/opencode/shots/final-game.png' });
  console.log('SNAP', JSON.stringify(await page.evaluate(() => window.WUMMI.snapshot())));
  console.log('VERSION', await page.evaluate(() => window.WUMMI.version + ' ' + window.WUMMI.developer));
  console.log('ERRORS', JSON.stringify(errors), 'CONSOLE', JSON.stringify(cerr));
  await browser.close();
})();
EOF
